  function mount(){const root=$('#fse-editor');if(!root||editor?.root===root)return;dispose();editor={root,c:blank(),dead:false,selected:-1,pointers:new Map(),history:[],objectURLs:new Set(),playing:true,pen:{color:'#ff5788',width:1,mode:'pen'},pending:false};document.body.classList.add('fse-active');root.addEventListener('click',click);root.addEventListener('change',change);root.addEventListener('input',input);root.addEventListener('submit',submit);editor.resize=()=>{root.style.setProperty('--fse-height',(window.visualViewport?.height||innerHeight)+'px');root.style.setProperty('--fse-offset',(window.visualViewport?.offsetTop||0)+'px');};visualViewport?.addEventListener('resize',editor.resize);visualViewport?.addEventListener('scroll',editor.resize);editor.resize();if(root.dataset.format==='reel'){editor.c.format='reel';window.FlixReels?.attach();}}
