  function paint(){const s=editor;if(!s||s.dead)return;s.player?.destroy();const root=$('#fse-canvas',s.root);root.innerHTML=stageMarkup(s.c,true);s.player=runtime(root,s.c,{editing:true,onTime:(t,d)=>s.onTime?.(t,d)});s.player.play();s.root.classList.toggle('has-media',!!s.c.items.length);$('.fse-select',s.root).hidden=!!s.c.items.length;$('.fse-tools',s.root).hidden=!s.c.items.length;$('.fse-publish',s.root).hidden=!s.c.items.length;$('.fse-video-tools',s.root).hidden=s.c.items[0]?.type!=='video';bindGestures(s);s.onPaint?.();}
  function repaintLayers(){const s=editor;if(!s)return;$('.cx-scene-layers',s.root).innerHTML=drawings(s.c)+s.c.layers.map((l,i)=>layerMarkup(l,i,true)).join('');}
  function newLayer(type,text,extra={}){const s=editor;if(s.c.layers.length>=20)throw Error('Use até 20 elementos no story.');remember();const l={id:crypto.randomUUID(),type,text,x:50,y:38,size:type==='emoji'?52:28,rotation:0,scale:1,color:'#ffffff',background:'#211526',backgroundOpacity:type==='text'||type==='emoji'?0:.8,font:'sans',align:'center',animation:'none',start:0,end:s.c.format==='reel'?60:30,...extra};s.c.layers.push(l);s.selected=s.c.layers.length-1;repaintLayers();return l;}
