  function closeSheet(){const s=editor;if(!s)return;$('.fse-sheet-host',s.root).replaceChildren();s.sheet='';$('.fse-tools',s.root).classList.remove('is-obscured');if(!s.drawing&&!s.textEditing)s.player?.play();}
