    scene.addEventListener('pointermove',e=>{if(s.stroke){drawMove(e,s,scene);return;}if(!gesture||!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});cancelAnimationFrame(raf);raf=requestAnimationFrame(()=>{if(!gesture)return;const now=center(),old=gesture.start,rect=gesture.rect,m=gesture.layer>=0?s.c.layers[gesture.layer]:s.c.items[0],b=gesture.item;gesture.moved=gesture.moved||Math.hypot(now.x-old.x,now.y-old.y)>3||pointers.size>1;if(gesture.layer>=0){m.x=clamp(b.x+(now.x-old.x)/rect.width*100,0,100);m.y=clamp(b.y+(now.y-old.y)/rect.height*100,0,100);if(now.d&&old.d){m.scale=clamp((b.scale||1)*now.d/old.d,.25,4);m.rotation=((b.rotation+now.a-old.a+540)%360)-180;}const el=$(`[data-layer="${gesture.layer}"]`,scene);el.style.transform=`translate3d(${m.x}cqw,${m.y}cqh,0) translate(-50%,-50%) rotate(${m.rotation}deg) scale(${m.scale})`;const trash=$('.fse-trash',s.root);trash.hidden=!gesture.moved;const tr=trash.getBoundingClientRect();trash.classList.toggle('is-over',now.x>=tr.left-20&&now.x<=tr.right+20&&now.y>=tr.top-20&&now.y<=tr.bottom+20);}else{m.panX=(b.panX||0)+(now.x-old.x)/rect.width;m.panY=(b.panY||0)+(now.y-old.y)/rect.height;if(now.d&&old.d)m.zoom=clamp(b.zoom*now.d/old.d,1,3);cropMedia($('.fse-source',scene),m,scene,rect);}});});
