  function drawStart(e,s,scene){if(s.c.drawings.length>=40&&s.pen.mode!=='eraser'){status('Use até 40 traços.');return;}remember();s.stroke={mode:s.pen.mode,rect:scene.getBoundingClientRect(),index:s.c.drawings.length};if(s.pen.mode!=='eraser')s.c.drawings.push({...s.pen,points:[]});scene.setPointerCapture(e.pointerId);drawMove(e,s,scene);}
  function drawMove(e,s,scene){const r=s.stroke.rect,p=[clamp((e.clientX-r.left)/r.width*100,0,100),clamp((e.clientY-r.top)/r.height*100,0,100)];if(s.stroke.mode==='eraser')s.c.drawings=s.c.drawings.filter(l=>!l.points.some(v=>Math.hypot((v[0]-p[0]),(v[1]-p[1])*r.height/r.width)<4));else{const l=s.c.drawings[s.stroke.index];if(l.points.length<500&&s.c.drawings.reduce((n,x)=>n+x.points.length,0)<5000)l.points.push(p);}cancelAnimationFrame(s.drawFrame);s.drawFrame=requestAnimationFrame(()=>{const old=$('.fse-drawing',scene);if(old)old.outerHTML=drawings(s.c);});}
