  function textEditor(index=-1){const s=editor;if(index<0){newLayer('text','');index=s.selected;}s.selected=index;s.textEditing=true;s.player.pause();const l=s.c.layers[index];s.root.classList.add('is-text-editing');const el=document.createElement('div');el.className='fse-text-edit';el.innerHTML=`<div class="fse-text-tools fse-glass"><select data-text="font" aria-label="Fonte">${Object.keys(fonts).map((k,i)=>`<option value="${k}" ${k===l.font?'selected':''}>${['Clássica','Editorial','Máquina','Redonda','Itálico'][i]}</option>`).join('')}</select>${B('text-align',icon('list'),'aria-label="Alinhamento"')}${B('text-bg','A','aria-label="Fundo do texto"')}<select data-text="animation" aria-label="Animação">${[['none','Sem animação'],['fade','Surgir'],['pop','Aparecer'],['pulse','Pulsar']].map(([k,v])=>`<option value="${k}" ${l.animation===k?'selected':''}>${v}</option>`).join('')}</select>${B('text-done','Concluir')}</div><div class="fse-color-list">${colors.map(c=>B('text-color','',`style="--swatch:${c}" data-color="${c}" aria-label="Cor ${c}"`)).join('')}</div><textarea aria-label="Texto do story" maxlength="240" placeholder="Sua história aqui" spellcheck="true">${esc(l.text)}</textarea>`;s.root.append(el);const area=$('textarea',el);area.style.color=l.color;area.style.fontFamily=fonts[l.font];area.style.textAlign=l.align;area.focus();area.setSelectionRange(area.value.length,area.value.length);}
  function finishText(){const s=editor,l=s.c.layers[s.selected];l.text=$('.fse-text-edit textarea',s.root).value.trim();if(!l.text)s.c.layers.splice(s.selected,1);$('.fse-text-edit',s.root).remove();s.textEditing=false;s.root.classList.remove('is-text-editing');repaintLayers();s.player.play();}
  function editLayer(index){const s=editor;s.selected=index;const l=s.c.layers[index];if(l.type==='text'){remember();textEditor(index);}else if(l.type==='link')linkForm(l);else if(l.type==='poll'||l.type==='question'||l.type==='location'||l.type==='hashtag')stickerForm(l.type,l);else sheet('Sua figurinha',`<p>Arraste, faça pinça para ampliar ou gire com dois dedos.</p>${B('remove-layer',icon('trash')+' Excluir figurinha','','fse-primary')}`);}
  function linkForm(l=null){form('Adicionar link',`<label>URL<input name="url" type="url" inputmode="url" autocomplete="off" placeholder="https://…" required value="${esc(l?.url||'')}"></label><label>Texto da figurinha<input name="text" maxlength="120" placeholder="Saiba mais" value="${esc(l?.text||'')}"></label><input type="hidden" name="layer" value="${l?editor.selected:-1}">`,'link','Adicionar link');}
  function stickers(){sheet('Figurinhas',`<div class="fse-sticker-types">${[['emoji','☺','Emojis'],['gif','GIF','GIF'],['location','⌖','Localização'],['poll','☷','Enquete'],['question','?','Pergunta'],['clock','◷','Horário'],['mention','@','Menção'],['hashtag','#','Hashtag']].map(([a,i,t])=>B('sticker-type',`<b>${i}</b><span>${t}</span>`,`data-kind="${a}"`)).join('')}</div><div class="fse-emoji-grid">${['🍿','🎬','❤️','🔥','✨','😂','😍','🥹','😱','🥰','💖','💜','🎮','🏆','🎵','🚀','👀','👋','👏','💯','🪩','🌈','⭐','🫶'].map(e=>B('emoji',e,`data-emoji="${e}" aria-label="Adicionar ${e}"`)).join('')}</div>`,'stickers');}
  function stickerForm(kind,l=null){const title={location:'Localização',poll:'Enquete',question:'Pergunta',hashtag:'Hashtag'}[kind];form(title,`<label>${{location:'Nome do lugar',poll:'Sua pergunta',question:'O que você quer perguntar?',hashtag:'Sua hashtag'}[kind]}<input name="text" maxlength="${kind==='hashtag'?60:160}" required value="${esc(l?.text||'')}"></label>${kind==='poll'?`<label>Opção 1<input name="one" maxlength="60" required value="${esc(l?.options?.[0]||'Sim')}"></label><label>Opção 2<input name="two" maxlength="60" required value="${esc(l?.options?.[1]||'Não')}"></label>`:''}<input type="hidden" name="kind" value="${kind}"><input type="hidden" name="layer" value="${l?editor.selected:-1}">`,'sticker','Adicionar figurinha');}
  function mention(){form('Mencionar alguém','<label>Nome de usuário<input name="query" placeholder="@usuário" minlength="2" maxlength="50" required autocomplete="off"></label><div class="fse-people-results"></div>','mention','Buscar pessoa');}
  function slider(label,key,value,min,max,step='.05'){return `<label>${label}<span class="fse-slider"><input type="range" data-adjust="${key}" min="${min}" max="${max}" step="${step}" value="${value}"><output>${value}</output></span></label>`;}
  function adjust(){const m=editor.c.items[0];sheet('Ajustar',`${slider('Brilho','brightness',m.brightness,.5,1.5)}${slider('Contraste','contrast',m.contrast,.5,1.5)}${slider('Saturação','saturation',m.saturation,0,2)}<div class="fse-filter-list">${[['none','Original'],['warm','Quente'],['cool','Frio'],['mono','P&B'],['vivid','Vibrante']].map(([k,t])=>B('filter',t,`data-filter="${k}" aria-pressed="${m.filter===k}"`)).join('')}</div>${m.type==='video'?`${slider('Áudio original','volume',m.volume,0,1)}<label>Velocidade<select data-adjust="speed">${[.25,.5,1,1.5,2,3].filter(v=>v<=m.sourceDuration).map(v=>`<option ${v===m.speed?'selected':''}>${v}</option>`).join('')}</select></label>${B('mute',icon('volume')+(m.volume?' Silenciar vídeo':' Ativar áudio original'))}${B('trim',icon('edit')+' Recortar vídeo')}`:slider('Duração do story (segundos)','duration',m.duration,1,30,'1')}${B('crop-reset','Redefinir enquadramento')}${B('sheet-close','Concluir','','fse-primary')}`,'adjust');}
  function draw(){const s=editor;s.drawing=true;s.player.pause();s.root.classList.add('is-drawing');const panel=document.createElement('div');panel.className='fse-draw-tools fse-glass';panel.innerHTML=`<label class="fse-color-input" aria-label="Cor do desenho"><input type="color" data-pen="color" value="${s.pen.color}"></label><input type="range" data-pen="width" aria-label="Espessura" min=".3" max="4" step=".1" value="${s.pen.width}">${[['pen','✎','Lápis'],['marker','▰','Marcador'],['neon','✦','Neon'],['eraser','▱','Borracha']].map(([a,i,t])=>B('brush',i,`data-brush="${a}" aria-label="${t}" aria-pressed="${a===s.pen.mode}"`)).join('')}${B('draw-undo',icon('rewind'),'aria-label="Desfazer desenho"')}${B('draw-done','Pronto')}`;s.root.append(panel);}
  async function music(){const song=editor.c.music;sheet('Música',`<form data-story-form="music-search"><label>Pesquisar música<input name="query" minlength="2" maxlength="100" placeholder="Música ou artista" required></label><button type="submit" class="fse-primary">Buscar</button><p class="fse-form-error"></p></form><div class="fse-music-results"></div><details><summary>Usar link ou arquivo de áudio</summary><form data-story-form="music-link"><label>Link<input name="url" type="url" required placeholder="YouTube, SoundCloud ou MP3"></label><button type="submit" class="fse-primary">Usar música</button><p class="fse-form-error"></p></form>${B('audio-upload',icon('upload')+' Enviar áudio')}</details>${song?`<section class="fse-music-selected"><h3>${esc(song.title)}</h3><label>Início do trecho (segundos)<input type="number" data-music="start" min="0" max="36000" step="1" value="${song.start}"></label><label>Volume<input type="range" data-music="volume" min="0" max="1" step=".05" value="${song.volume}"></label><p>O trecho acompanha os ${total(editor.c).toFixed(1)} segundos do story.</p>${B('music-preview',icon('play')+' Ouvir prévia')}${B('music-remove','Remover música')}</section>`:''}${B('sheet-close','Concluir','','fse-primary')}`,'music');}
  async function chooseMusic(song){remember();editor.c.music=song;closeSheet();paint();await music();}
  async function people(mode,publishAfter=false){const s=editor;status('Carregando amigos…');const d=await A('/story-audience');if(s.dead)return;s.friends=d.friends;s.peopleMode=mode;s.publishAfter=publishAfter;status('');sheet(mode==='close'?'Amigos próximos':'Enviar para',`<p>${mode==='close'?'Só as pessoas selecionadas poderão ver seus stories de amigos próximos.':'O story será enviado no chat e ficará visível apenas para os amigos selecionados.'}</p><form data-story-form="people"><div class="fse-friends">${d.friends.map(u=>`<label>${C().avatar(u)}<span><strong>${esc(u.name)}</strong><small>@${esc(u.username)}</small></span><input type="checkbox" name="person" value="${esc(u.id)}" ${mode==='close'&&u.close?'checked':''}></label>`).join('')||'<p>Adicione amigos na comunidade para compartilhar com eles.</p>'}</div><p class="fse-form-error"></p><button type="submit" class="fse-primary" ${d.friends.length?'':'disabled'}>${mode==='close'?publishAfter?'Salvar e compartilhar':'Salvar lista':'Enviar story'}</button></form>`,'people');}
  async function thumbnail(s){const m=s.c.items[0],media=$('.fse-source',s.root),canvas=document.createElement('canvas');canvas.width=360;canvas.height=640;const ctx=canvas.getContext('2d'),mw=media.naturalWidth||media.videoWidth,mh=media.naturalHeight||media.videoHeight;if(!mw||!mh)return m.type==='image'?m.url:'';const k=Math.max(360/mw,640/mh)*m.zoom;ctx.filter=filter(m);ctx.drawImage(media,(360-mw*k)/2+(m.panX||0)*360,(640-mh*k)/2+(m.panY||0)*640,mw*k,mh*k);ctx.filter='none';for(const line of s.c.drawings){ctx.strokeStyle=line.color;ctx.lineWidth=line.width*3.6;ctx.lineCap='round';ctx.globalAlpha=line.mode==='marker'?.4:1;ctx.beginPath();line.points.forEach((p,i)=>i?ctx.lineTo(p[0]*3.6,p[1]*6.4):ctx.moveTo(p[0]*3.6,p[1]*6.4));ctx.stroke();}ctx.globalAlpha=1;for(const l of s.c.layers){if(l.type==='gif')continue;ctx.save();ctx.translate(l.x*3.6,l.y*6.4);ctx.rotate(l.rotation*Math.PI/180);ctx.scale(l.scale,l.scale);ctx.font=`600 ${l.size}px ${fonts[l.font]||fonts.sans}`;ctx.fillStyle=l.color;ctx.textAlign=l.align;ctx.textBaseline='middle';l.text.split('\n').forEach((text,i)=>ctx.fillText(text,0,i*l.size*1.15,320));ctx.restore();}const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));return blob?(await CommunitySocial.upload(new File([blob],'story-cover.png',{type:'image/png'}),true)).url:'';}
  async function publish(audience='public',recipients=[]){const s=editor;if(s.publishing)return;if(s.pending)throw Error('Espere o envio da mídia terminar.');if(!s.c.items.length)throw Error('Escolha uma foto ou um vídeo.');if(s.c.items[0].url.startsWith('blob:'))throw Error('O envio não terminou. Selecione a mídia novamente na galeria.');if(total(s.c)>30)throw Error('Escolha um trecho de até 30 segundos.');s.publishing=true;s.player.pause();status('Publicando seu story…');s.root.classList.add('is-publishing');try{const cover=await thumbnail(s);if(s.dead)return;const result=await A('/stories','POST',{body:s.c.layers.find(l=>l.type==='text')?.text||'',composition:s.c,thumbnail:cover,audience,recipients});if(s.dead)return;toast(audience==='selected'?'Story enviado!':'Story publicado!');await navigate('/comunidade');return result;}finally{s.publishing=false;if(!s.dead){s.root.classList.remove('is-publishing');status('');}}}
  async function camera(){const s=editor;sheet('Câmera',`<video class="fse-camera-preview" autoplay muted playsinline></video><div class="fse-camera-mode">${B('camera-mode','Foto','data-mode="photo" aria-pressed="true"')}${B('camera-mode','Vídeo','data-mode="video" aria-pressed="false"')}</div><output class="fse-record-time">00:00 / 00:30</output>${B('capture',icon('camera'),'aria-label="Capturar foto"','fse-shutter')}${B('camera-switch','Trocar câmera')}`,'camera');s.cameraMode='photo';s.cameraFacing||='environment';
    if(!navigator.mediaDevices?.getUserMedia){$('#fse-capture-fallback',s.root).click();closeSheet();return;}
    stopCamera(s);try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:s.cameraFacing},width:{ideal:1080},height:{ideal:1920}},audio:false});if(s.dead||s.sheet!=='camera'){stream.getTracks().forEach(t=>t.stop());return;}s.cameraStream=stream;$('.fse-camera-preview',s.root).srcObject=stream;}catch(_){closeSheet();$('#fse-capture-fallback',s.root).click();}}
  function stopCamera(s){clearTimeout(s.recordTimer);clearInterval(s.recordClock);if(s.recorder&&s.recorder.state!=='inactive'){s.cancelRecording=true;s.recorder.stop();}s.cameraStream?.getTracks().forEach(t=>t.stop());s.cameraStream=null;}
  async function capture(){const s=editor,v=$('.fse-camera-preview',s.root);if(!s.cameraStream||!v?.videoWidth)throw Error('Aguarde a câmera abrir.');if(s.cameraMode==='photo'){const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));stopCamera(s);await loadFile(new File([blob],'foto.png',{type:'image/png'}));return;}
    if(s.recorder?.state==='recording'){if(performance.now()-s.recordStarted<1100)return;s.recorder.stop();return;}if(!window.MediaRecorder){$('#fse-capture-fallback',s.root).accept='video/*';$('#fse-capture-fallback',s.root).click();stopCamera(s);closeSheet();return;}
    try{const audio=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true},video:false});if(s.dead||s.sheet!=='camera'){audio.getTracks().forEach(t=>t.stop());return;}audio.getAudioTracks().forEach(t=>s.cameraStream.addTrack(t));}catch(_){status('Gravando vídeo sem microfone.');}
    const mime=['video/mp4;codecs=avc1.42E01E,mp4a.40.2','video/mp4','video/webm;codecs=vp8,opus','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)throw Error('Use a câmera do aparelho para gravar o vídeo.');const chunks=[];s.cancelRecording=false;s.recorder=new MediaRecorder(s.cameraStream,{mimeType:mime,videoBitsPerSecond:2000000});const recorder=s.recorder,started=performance.now();s.recordStarted=started;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=async()=>{clearTimeout(s.recordTimer);clearInterval(s.recordClock);const duration=Math.min(30,(performance.now()-started)/1000);s.recorder=null;s.cameraStream?.getTracks().forEach(t=>t.stop());s.cameraStream=null;if(s.dead||s.cancelRecording)return;try{await loadFile(new File(chunks,'camera.'+(mime.includes('mp4')?'mp4':'webm'),{type:mime.split(';')[0]}),duration);}catch(e){status(e.message);}};recorder.start(250);$('.fse-shutter',s.root).innerHTML=icon('stop');$('.fse-shutter',s.root).setAttribute('aria-label','Parar gravação');s.recordClock=setInterval(()=>{const label=$('.fse-record-time',s.root);if(label)label.textContent=timecode(Math.min(30,(performance.now()-started)/1000))+' / 00:30';},150);s.recordTimer=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},30000);}
  async function click(e){const b=e.target.closest('[data-story]'),s=editor;if(!b||!s||b.disabled||s.publishing)return;e.preventDefault();const a=b.dataset.story;
    try{
      if(a==='gallery'){$('#fse-gallery',s.root).click();return;}
      if(a==='back'){if(!s.c.items.length&&!s.pending){navigate('/comunidade');return;}sheet('Sair do editor?',`<p>As alterações deste story ainda não foram publicadas.</p>${B('discard','Descartar story','','fse-primary')}${B('sheet-close','Continuar editando')}`);return;}
      if(a==='discard'){await navigate('/comunidade');return;}
      if(a==='sheet-close'){if(s.sheet==='trim'&&s.trimRequired){status('Escolha o trecho e toque em Usar trecho.');return;}if(s.sheet==='camera')stopCamera(s);closeSheet();return;}
      if(a==='options'){sheet('Opções do story',`${B('gallery',icon('storyGallery')+' Trocar mídia')}${B('edit-close',icon('storyStar')+' Editar amigos próximos')}${B('undo',icon('rewind')+' Desfazer última alteração')}${B('back',icon('trash')+' Descartar story')}`);return;}
      if(a==='camera'){await camera();return;}if(a==='camera-switch'){s.cameraFacing=s.cameraFacing==='environment'?'user':'environment';await camera();return;}
      if(a==='camera-mode'){if(s.recorder?.state==='recording')return;s.cameraMode=b.dataset.mode;$$('[data-story=camera-mode]',s.root).forEach(el=>el.setAttribute('aria-pressed',el===b));$('.fse-shutter',s.root).setAttribute('aria-label',s.cameraMode==='video'?'Gravar vídeo':'Capturar foto');return;}
      if(a==='capture'){await capture();return;}
      if(a==='text'){textEditor();return;}if(a==='text-done'){finishText();return;}
      if(a==='text-color'){s.c.layers[s.selected].color=b.dataset.color;$('.fse-text-edit textarea',s.root).style.color=b.dataset.color;return;}
      if(a==='text-align'){const l=s.c.layers[s.selected];l.align={left:'center',center:'right',right:'left'}[l.align];$('.fse-text-edit textarea',s.root).style.textAlign=l.align;return;}
      if(a==='text-bg'){const l=s.c.layers[s.selected];l.backgroundOpacity=l.backgroundOpacity?0:.85;$('.fse-text-edit textarea',s.root).style.background=l.backgroundOpacity?'#211526cc':'transparent';return;}
      if(a==='link'){linkForm();return;}if(a==='stickers'){stickers();return;}
      if(a==='emoji'){newLayer('emoji',b.dataset.emoji);closeSheet();return;}
      if(a==='sticker-type'){const kind=b.dataset.kind;if(kind==='emoji')return;if(kind==='gif'){$('#fse-gif',s.root).click();return;}if(kind==='clock'){newLayer('clock',new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}));closeSheet();return;}if(kind==='mention'){mention();return;}stickerForm(kind);return;}
      if(a==='mention-pick'){const person=s.people[+b.dataset.index];newLayer('mention','@'+person.username,{user_id:person.id,url:'/comunidade/perfil/'+person.username,size:24,backgroundOpacity:.8});closeSheet();return;}
      if(a==='remove-layer'){remember();s.c.layers.splice(s.selected,1);repaintLayers();closeSheet();return;}
      if(a==='draw'){draw();return;}if(a==='brush'){s.pen.mode=b.dataset.brush;$$('[data-story=brush]',s.root).forEach(el=>el.setAttribute('aria-pressed',el===b));return;}
      if(a==='draw-done'){s.drawing=false;s.root.classList.remove('is-drawing');$('.fse-draw-tools',s.root)?.remove();s.player.play();return;}
      if(a==='draw-undo'||a==='undo'){if(s.history.length){s.c=JSON.parse(s.history.pop());if(a==='draw-undo')repaintLayers();else{closeSheet();paint();}}return;}
      if(a==='adjust'){remember();adjust();return;}if(a==='filter'){s.c.items[0].filter=b.dataset.filter;$$('[data-story=filter]',s.root).forEach(el=>el.setAttribute('aria-pressed',el===b));s.player.refresh();return;}
      if(a==='crop-reset'){Object.assign(s.c.items[0],{zoom:1,panX:0,panY:0});s.player.refresh();return;}
      if(a==='mute'){s.c.items[0].volume=s.c.items[0].volume?0:1;s.player.refresh();adjust();return;}if(a==='trim'){trim();return;}
      if(a==='play'){s.player.playing?s.player.pause():s.player.play(true);b.innerHTML=icon(s.player.playing?'pause':'play');b.setAttribute('aria-label',s.player.playing?'Pausar prévia':'Reproduzir prévia');return;}if(a==='sound'){s.player.play(true);status('Som da prévia ativado.');return;}
      if(a==='music'){await music();return;}if(a==='music-pick'){const song=s.musicResults[+b.dataset.index];await chooseMusic({url:song.url,type:'youtube',title:song.title,start:0,volume:.6});return;}
      if(a==='music-preview'){s.player.play(true);b.textContent='Ouvindo prévia';return;}if(a==='music-remove'){remember();s.c.music=null;closeSheet();paint();return;}
      if(a==='audio-upload'){$('#fse-audio',s.root).click();return;}
      if(a==='publish'){await publish();return;}if(a==='send'){await people('selected');return;}
      if(a==='close-friends'){const d=await A('/story-audience');if(d.friends.some(u=>u.close))await publish('close');else await people('close',true);return;}
      if(a==='edit-close'){await people('close');return;}
    }catch(error){status(error.message);}
  }
  async function change(e){const s=editor;if(!s)return;const el=e.target;try{if(el.id==='fse-gallery'||el.id==='fse-capture-fallback'){if(el.files[0])await loadFile(el.files[0]);el.value='';return;}
    if(el.id==='fse-gif'){const file=el.files[0];if(!file)return;if(file.type!=='image/gif'||file.size>4*1024*1024)throw Error('Escolha um GIF de até 4 MB.');const body=new FormData();body.append('file',file);const r=await fetch('/api/community/assets',{method:'POST',headers:{'X-Requested-With':'Flix'},body}),d=await r.json();if(!r.ok)throw Error(d.error);if(s.dead)return;newLayer('gif','GIF',{url:d.url,size:60});closeSheet();el.value='';return;}
    if(el.id==='fse-audio'){const file=el.files[0];if(!file)return;status('Enviando música…');const d=await CommunitySocial.upload(file,false);if(s.dead)return;if(d.media_type!=='audio')throw Error('Escolha um arquivo de áudio.');await chooseMusic({url:d.url,type:'audio',title:file.name,start:0,volume:.6});status('');el.value='';return;}
    if(el.dataset.text){const l=s.c.layers[s.selected];l[el.dataset.text]=el.value;if(el.dataset.text==='font')$('.fse-text-edit textarea',s.root).style.fontFamily=fonts[el.value];}
    if(el.dataset.adjust==='speed'){const m=s.c.items[0],span=m.duration*m.speed;m.speed=+el.value;m.duration=Math.min(30,span/m.speed);s.player.refresh();trim();}
  }catch(error){status(error.message);}}
  function input(e){const s=editor;if(!s)return;const el=e.target;if(el.closest('[data-story-form=trim]'))trimLabel(el.name);if(el.dataset.pen)s.pen[el.dataset.pen]=el.dataset.pen==='color'?el.value:+el.value;
    if(el.dataset.adjust&&el.dataset.adjust!=='speed'){s.c.items[0][el.dataset.adjust]=+el.value;if(el.nextElementSibling?.tagName==='OUTPUT')el.nextElementSibling.value=el.value;s.player.refresh();}
    if(el.dataset.music){s.c.music[el.dataset.music]=+el.value;if(el.dataset.music==='start')s.player.seek(0);s.player.refresh();}
  }
  async function submit(e){const f=e.target;if(!f.matches('[data-story-form]'))return;e.preventDefault();const s=editor,d=Object.fromEntries(new FormData(f)),kind=f.dataset.storyForm,button=$('[type=submit]',f);if(button.disabled)return;button.disabled=true;const err=$('.fse-form-error',f);if(err)err.textContent='';try{
    if(kind==='trim'){const m=s.c.items[0],start=+d.start,span=d.end-start;if(span/(m.speed||1)<.999||span/(m.speed||1)>30.01||+d.end>m.sourceDuration+.01)throw Error('Escolha um trecho de até 30 segundos.');remember();m.start=start;m.duration=Math.min(30,span/(m.speed||1));s.trimRequired=false;closeSheet();s.player.seek(0);s.player.play();status('');}
    if(kind==='link'){const url=new URL(d.url);if(url.protocol!=='https:')throw Error('Use um link HTTPS.');const val={text:d.text.trim()||'Saiba mais',url:url.href};if(+d.layer>=0){remember();Object.assign(s.c.layers[+d.layer],val);repaintLayers();}else newLayer('link',val.text,{...val,size:22,backgroundOpacity:.9});closeSheet();}
    if(kind==='sticker'){const extra={};let text=d.text.trim();if(d.kind==='hashtag')text='#'+text.replace(/^#+/,'').replace(/\s+/g,'');if(d.kind==='poll'){if(d.one.trim()===d.two.trim())throw Error('Use opções diferentes.');extra.options=[d.one.trim(),d.two.trim()];}if(+d.layer>=0){remember();Object.assign(s.c.layers[+d.layer],extra,{text});repaintLayers();}else newLayer(d.kind,text,{...extra,size:24,backgroundOpacity:.92});closeSheet();}
    if(kind==='mention'){const found=await A('/publishing/search?kind=people&q='+encodeURIComponent(d.query));if(s.dead)return;s.people=found.items;$('.fse-people-results',f).innerHTML=found.items.map((u,i)=>B('mention-pick',C().person(u),`data-index="${i}"`)).join('')||'<p>Nenhuma pessoa encontrada.</p>';}
    if(kind==='music-search'){const found=await A('/music/search?q='+encodeURIComponent(d.query));if(s.dead)return;s.musicResults=found.items;$('.fse-music-results',s.root).innerHTML=found.items.map((m,i)=>B('music-pick',`<img src="${esc(m.image)}" alt=""><span><strong>${esc(m.title)}</strong><small>${esc(m.artist)}</small></span>`,`data-index="${i}"`)).join('')||`<p>${esc(found.message||'Nenhuma música encontrada.')}</p>`;}
    if(kind==='music-link'){const u=new URL(d.url);if(u.protocol!=='https:')throw Error('Use um link HTTPS.');const id=CommunityRoom.youtubeId(d.url),yt=['youtube.com','www.youtube.com','m.youtube.com','youtu.be'].includes(u.hostname),sc=['soundcloud.com','www.soundcloud.com'].includes(u.hostname);if(yt&&!id)throw Error('Link do YouTube inválido.');if(!yt&&!sc&&!/\.(mp3|m4a|wav|ogg)(?:[?#]|$)/i.test(d.url))throw Error('Use YouTube, SoundCloud ou um arquivo de áudio.');await chooseMusic({url:yt?'https://www.youtube.com/watch?v='+id:d.url,type:yt?'youtube':sc?'soundcloud':'audio',title:'Minha música',start:0,volume:.6});}
    if(kind==='people'){const ids=new FormData(f).getAll('person');if(s.peopleMode==='close'){await A('/story-audience','PUT',{users:ids});if(s.publishAfter){if(!ids.length)throw Error('Selecione pelo menos um amigo.');await publish('close');}else closeSheet();}else{if(!ids.length)throw Error('Selecione pelo menos um amigo.');await publish('selected',ids);}}
  }catch(error){if(err)err.textContent=error.message;else status(error.message);}finally{if(button.isConnected)button.disabled=false;}}
  function decorateStory(story){
    const root=$('#modal .cx-viewer'),isReel=story.composition?.format==='reel',base='/'+(isReel?'reels':'stories')+'/'+story.id;if(!root||!['story','reel'].includes(story.composition?.format))return;
    root.classList.add('fse-story-view');let answering=false;
    root.addEventListener('click',async e=>{
      const b=e.target.closest('[data-story-interact]');if(!b||answering)return;
      answering=true;const resume=FlixCreate.pauseViewer(),l=story.composition.layers[+b.dataset.storyInteract];
      try{
        const result=await A(base+'/stickers/'+l.id);if(!root.isConnected)return;
        const box=document.createElement('section');box.className='fse-response fse-glass';box.setAttribute('role','dialog');box.setAttribute('aria-label',l.text);
        box.innerHTML=`<button type="button" class="fse-response-close" aria-label="Fechar">×</button><h3>${esc(l.text)}</h3>${l.type==='poll'?l.options.map((o,i)=>`<button type="button" data-choice="${i}">${esc(o)} <small>${result.counts[i]} voto(s)</small></button>`).join(''):`<form><label>Sua resposta<input name="answer" maxlength="240" required value="${esc(result.mine||'')}"></label><button type="submit">Enviar</button></form>${story.user_id===state.user.id?(result.answers||[]).map(a=>`<p><strong>@${esc(a.username)}</strong> ${esc(JSON.parse(a.value))}</p>`).join(''):''}`}<p class="fse-answer-status" role="status"></p>`;
        $('#modal').append(box);$('.fse-response-close',box).onclick=()=>{box.remove();answering=false;resume();};
        $$('[data-choice]',box).forEach(el=>el.onclick=async()=>{
          $$('[data-choice]',box).forEach(btn=>btn.disabled=true);
          try{const data=await A(base+'/stickers/'+l.id,'POST',{value:+el.dataset.choice});$$('[data-choice]',box).forEach(btn=>{$('small',btn).textContent=data.counts[+btn.dataset.choice]+' voto(s)';btn.setAttribute('aria-pressed',+btn.dataset.choice===data.mine);});$('.fse-answer-status',box).textContent='Voto registrado!';}
          catch(err){$('.fse-answer-status',box).textContent=err.message;}
          finally{$$('[data-choice]',box).forEach(btn=>btn.disabled=false);}
        });
        $('form',box)?.addEventListener('submit',async ev=>{
          ev.preventDefault();const button=$('[type=submit]',box);if(button.disabled)return;button.disabled=true;
          try{await A(base+'/stickers/'+l.id,'POST',{value:new FormData(ev.target).get('answer')});$('.fse-answer-status',box).textContent='Resposta enviada!';}
          catch(err){$('.fse-answer-status',box).textContent=err.message;}
          finally{button.disabled=false;}
        });
      }catch(error){answering=false;resume();toast(error.message);}
    });
  }
